+     */
+    public void verifyCode(PendingSocialLogin pending, CodeTarget target, String code) {
+        String hash =
+                guarded(
+                        () ->
+                                guard.reserveCodeAttempt(
+                                        pending.verificationId(),
+                                        target,
+                                        linkTargetOf(pending, target)));
