+                    pending.provider().registrationId(),
+                    pending.stage().name(),
+                    pending.email(),
+                    pending.providerNickname(),
+                    pending.linkReason().name(),
+                    null,
+                    PHONE_MATCH_METHODS,
+                    pending.expiresAt());
