+        SocialLoginOutcome outcome = socialLoginService.advance(pending.withEmailVerified());
+        return switch (outcome.type()) {
+            case ACCOUNT_UNAVAILABLE ->
+                    throw new BusinessException(ErrorCode.SOCIAL_SIGNUP_REJECTED);
